  1→import {
  2→  Injectable,
  3→  HttpException,
  4→  HttpStatus,
  5→  BadRequestException,
  6→  ConflictException,
  7→  NotFoundException,
  8→  Logger,
  9→  Inject,
 10→  forwardRef,
 11→} from '@nestjs/common';
 12→import { InjectRepository } from '@nestjs/typeorm';
 13→import { Repository } from 'typeorm';
 14→import { FolderIpns } from './entities/folder-ipns.entity';
 15→import {
 16→  PublishIpnsDto,
 17→  PublishIpnsEntryDto,
 18→  PublishIpnsResponseDto,
 19→  BatchPublishIpnsDto,
 20→  BatchPublishIpnsResponseDto,
 21→} from './dto';
 22→import { RepublishService } from '../republish/republish.service';
 23→import { DelegatedRoutingClient } from './delegated-routing.client';
 24→import { MetricsService } from '../metrics/metrics.service';
 25→import { parseIpnsRecord } from './ipns-record-parser';
 26→import { SharesService } from '../shares/shares.service';
 27→
 28→@Injectable()
 29→export class IpnsService {
 30→  private readonly logger = new Logger(IpnsService.name);
 31→
 32→  constructor(
 33→    @InjectRepository(FolderIpns)
 34→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 35→    private readonly delegatedRouting: DelegatedRoutingClient,
 36→    @Inject(forwardRef(() => RepublishService))
 37→    private readonly republishService: RepublishService,
 38→    private readonly metricsService: MetricsService,
 39→    private readonly sharesService: SharesService
 40→  ) {}
 41→
 42→  /**
 43→   * Publish a pre-signed IPNS record to the IPFS network via delegated routing
 44→   * and track the folder in the database for TEE republishing
 45→   */
 46→  async publishRecord(
 47→    userId: string,
 48→    dto: PublishIpnsDto | PublishIpnsEntryDto,
 49→    recordType: 'folder' | 'file' = 'folder'
 50→  ): Promise<PublishIpnsResponseDto> {
 51→    const endTimer = this.metricsService.ipfsIpnsDuration.startTimer({
 52→      operation: 'publish',
 53→      source: '',
 54→    });
 55→    let result = 'success';
 56→
 57→    try {
 58→      // Validate base64 record
 59→      let recordBytes: Uint8Array;
 60→      try {
 61→        recordBytes = Uint8Array.from(atob(dto.record), (c) => c.charCodeAt(0));
 62→      } catch {
 63→        throw new BadRequestException('Invalid base64-encoded record');
 64→      }
 65→
 66→      // Save to DB first so resolve always has a fallback, even if delegated
 67→      // routing fails (e.g. rate-limited, network error, DHT propagation delay).
 68→      const folder = await this.upsertFolderIpns(
 69→        userId,
 70→        dto.ipnsName,
 71→        dto.metadataCid,
 72→        dto.encryptedIpnsPrivateKey,
 73→        dto.keyEpoch,
 74→        recordType,
 75→        dto.expectedSequenceNumber
 76→      );
 77→
 78→      // Publish to delegated routing API (fire-and-forget — DB is the reliable source).
 79→      // DHT propagation via someguy takes ~10-30s per record. Since the DB record
 80→      // is already saved and resolveRecord() always checks/prefers DB data, there is
 81→      // no need to block the API response on DHT propagation. Metrics are still
 82→      // collected via the detached promise chain (catch + then).
 83→      const publishStart = process.hrtime.bigint();
 84→      this.delegatedRouting
 85→        .publish(dto.ipnsName, recordBytes)
 86→        .catch((error) => {
 87→          this.logger.warn(
 88→            `Delegated routing publish failed for ${dto.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
 89→          );
 90→          return 'error' as const;
 91→        })
 92→        .then((outcome) => {
 93→          const publishElapsed = Number(process.hrtime.bigint() - publishStart) / 1e9;
 94→          this.metricsService.ipnsPublishDuration.observe(
 95→            { outcome: outcome === 'error' ? 'error' : 'success' },
 96→            publishElapsed
 97→          );
 98→        })
 99→        .catch((error) => {
100→          this.logger.error(
101→            `Failed to record IPNS publish metrics for ${dto.ipnsName}: ${error instanceof Error ? error.message : String(error)}`
102→          );
103→        });
104→
105→      return {
106→        success: true,
107→        ipnsName: dto.ipnsName,
108→        sequenceNumber: folder.sequenceNumber,
109→      };
110→    } catch (error) {
111→      result = 'error';
112→      throw error;
113→    } finally {
114→      endTimer({ result });
115→    }
116→  }
117→
118→  /**
119→   * Batch publish multiple IPNS records with concurrency-limited processing.
120→   * Supports partial success: individual record failures do not fail the batch.
121→   * Processes up to 10 records concurrently.
122→   */
123→  async publishBatch(
124→    userId: string,
125→    dto: BatchPublishIpnsDto
126→  ): Promise<BatchPublishIpnsResponseDto> {
127→    const results: PublishIpnsResponseDto[] = [];
128→    let totalSucceeded = 0;
129→    let totalFailed = 0;
130→
131→    const CONCURRENCY = 10;
132→
133→    // Process records in batches of CONCURRENCY, delegating to publishRecord
134→    for (let i = 0; i < dto.records.length; i += CONCURRENCY) {
135→      const batch = dto.records.slice(i, i + CONCURRENCY);
136→
137→      const settled = await Promise.allSettled(
138→        batch.map((entry) => this.publishRecord(userId, entry, entry.recordType ?? 'folder'))
139→      );
140→
141→      for (let j = 0; j < settled.length; j++) {
142→        const result = settled[j];
143→        if (result.status === 'fulfilled') {
144→          results.push(result.value);
145→          totalSucceeded++;
146→        } else {
147→          const reason = result.reason;
148→          // If any record (especially a folder record) has a conflict, fail the entire batch
149→          if (reason instanceof ConflictException) {
150→            throw reason;
151→          }
152→          const ipnsName = batch[j]?.ipnsName ?? 'unknown';
153→          this.logger.warn(
154→            `Batch publish failed for ${ipnsName}: ${reason instanceof Error ? reason.message : String(reason)}`
155→          );
156→          results.push({
157→            success: false,
158→            ipnsName,
159→            sequenceNumber: '0',
160→          });
161→          totalFailed++;
162→        }
163→      }
164→    }
165→
166→    return { results, totalSucceeded, totalFailed };
167→  }
168→
169→  /**
170→   * Create or update a folder/file IPNS entry.
171→   * Handles both folder metadata and per-file metadata IPNS records.
172→   */
173→  private async upsertFolderIpns(
174→    userId: string,
175→    ipnsName: string,
176→    metadataCid: string,
177→    encryptedIpnsPrivateKey?: string,
178→    keyEpoch?: number,
179→    recordType: 'folder' | 'file' = 'folder',
180→    expectedSequenceNumber?: string
181→  ): Promise<FolderIpns> {
182→    let existing = await this.getFolderIpns(userId, ipnsName);
183→
184→    // If not the owner, check for active write share authorization.
185→    // When no owner record is found AND a write share exists, look up
186→    // the owner's FolderIpns by ipnsName. When no write share exists,
187→    // fall through to the create-new-entry path (owner's first publish).
188→    if (!existing) {
189→      const writeShare = await this.sharesService.findActiveWriteShare(userId, ipnsName);
190→      if (writeShare) {
191→        // Look up the sharer's FolderIpns record using their userId from the share
192→        existing = await this.folderIpnsRepository.findOne({
193→          where: { userId: writeShare.sharerId, ipnsName },
194→        });
195→        if (!existing) {
196→          throw new NotFoundException('IPNS name not found');
197→        }
198→      }
199→    }
200→
201→    // Conflict detection: when expectedSequenceNumber is provided, verify it matches
202→    if (existing && expectedSequenceNumber !== undefined) {
203→      const expected = BigInt(expectedSequenceNumber);
204→      const current = BigInt(existing.sequenceNumber);
205→      if (expected !== current) {
206→        throw new ConflictException({
207→          statusCode: 409,
208→          message: 'Sequence number mismatch: folder was modified by another device',
209→          currentSequenceNumber: existing.sequenceNumber,
210→          expectedSequenceNumber,
211→        });
212→      }
213→    }
214→
215→    if (existing) {
216→      // Update existing entry
217→      existing.latestCid = metadataCid;
218→      existing.sequenceNumber = (BigInt(existing.sequenceNumber) + 1n).toString();
219→      existing.recordType = recordType;
220→      existing.updatedAt = new Date();
221→
222→      // Only update encrypted key if provided (e.g., on key rotation).
223→      // Guard: only the owner can update TEE enrollment fields — write-share
224→      // recipients must not overwrite encryptedIpnsPrivateKey or keyEpoch.
225→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined && existing.userId === userId) {
226→        existing.encryptedIpnsPrivateKey = Buffer.from(encryptedIpnsPrivateKey, 'hex');
227→        existing.keyEpoch = keyEpoch;
228→      }
229→
230→      const saved = await this.folderIpnsRepository.save(existing);
231→
232→      // Auto-enroll for TEE republishing when encrypted key is provided.
233→      // Use existing.userId (the FolderIpns owner) for enrollment, not the
234→      // authenticated user — a write-share recipient publishes to the owner's record.
235→      if (encryptedIpnsPrivateKey && keyEpoch !== undefined && existing.userId === userId) {
236→        this.republishService
237→          .enrollFolder(
238→            existing.userId,
239→            ipnsName,
240→            Buffer.from(encryptedIpnsPrivateKey, 'hex'),
241→            keyEpoch,
242→            metadataCid,
243→            saved.sequenceNumber
244→          )
245→          .catch((err) =>
246→            this.logger.warn(
247→              `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
248→            )
249→          );
250→      }
251→
252→      return saved;
253→    }
254→
255→    // Create new entry — sequence starts at '1' to match the IPNS record
256→    // the client signed (clients compute newSeq = 0n + 1n = 1n for first publish).
257→    const folder = this.folderIpnsRepository.create({
258→      userId,
259→      ipnsName,
260→      latestCid: metadataCid,
261→      sequenceNumber: '1',
262→      encryptedIpnsPrivateKey: encryptedIpnsPrivateKey
263→        ? Buffer.from(encryptedIpnsPrivateKey, 'hex')
264→        : null,
265→      keyEpoch: keyEpoch ?? null,
266→      isRoot: false, // Root folder is tracked in Vault entity
267→      recordType,
268→    });
269→
270→    const saved = await this.folderIpnsRepository.save(folder);
271→
272→    // Auto-enroll for TEE republishing when encrypted key is provided
273→    if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
274→      this.republishService
275→        .enrollFolder(
276→          userId,
277→          ipnsName,
278→          Buffer.from(encryptedIpnsPrivateKey, 'hex'),
279→          keyEpoch,
280→          metadataCid,
281→          saved.sequenceNumber
282→        )
283→        .catch((err) =>
284→          this.logger.warn(
285→            `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
286→          )
287→        );
288→    }
289→
290→    return saved;
291→  }
292→
293→  /**
294→   * Get a folder IPNS entry by user and IPNS name
295→   */
296→  async getFolderIpns(userId: string, ipnsName: string): Promise<FolderIpns | null> {
297→    return this.folderIpnsRepository.findOne({
298→      where: { userId, ipnsName },
299→    });
300→  }

  1→import {
  2→  Controller,
  3→  Post,
  4→  Get,
