    it('should update existing keys (upsert)', async () => {
      const existingKey = {
        id: 'k1',
        shareId,
        keyType: 'file',
        itemId: '880e8400-e29b-41d4-a716-446655440003',
        encryptedKey: Buffer.from('aa'.repeat(32), 'hex'),
